import{_ as o,o as t,c as n,ah as i}from"./chunks/framework.ChH6X6u6.js";const g=JSON.parse('{"title":"Your children and their documents","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/parent/enfants-et-documents.md","filePath":"src/en/guide/parent/enfants-et-documents.md"}'),r={name:"en/guide/parent/enfants-et-documents.md"};function a(s,e,l,c,d,h){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="your-children-and-their-documents" tabindex="-1">Your children and their documents <a class="header-anchor" href="#your-children-and-their-documents" aria-label="Permalink to &quot;Your children and their documents&quot;">​</a></h1><p>This page explains how to find your children in ERA, follow their school record and download every document about them.</p><h2 id="seeing-your-children" tabindex="-1">Seeing your children <a class="header-anchor" href="#seeing-your-children" aria-label="Permalink to &quot;Seeing your children&quot;">​</a></h2><p>The <strong>My children</strong> page (left-hand menu) lists every child linked to your account, each as a card showing their class, annual average and payment balance. Click a card to open that child&#39;s full record.</p><p>If no child shows up yet, your school needs to link your account to your child&#39;s record first — or you may be able to do it yourself if this feature is enabled (see below).</p><h2 id="linking-a-child-to-your-account" tabindex="-1">Linking a child to your account <a class="header-anchor" href="#linking-a-child-to-your-account" aria-label="Permalink to &quot;Linking a child to your account&quot;">​</a></h2><p>If your school has enabled self-service linking, a <strong>Link a child</strong> entry appears in the left-hand menu. To link a child who is already enrolled to your account:</p><ol><li>Open <strong>Link a child</strong>.</li><li>In the search form, enter the child&#39;s <strong>First name</strong>, <strong>Last name</strong> and <strong>Date of birth</strong>, then click <strong>Search</strong>.</li><li>In the results, click <strong>Link</strong> next to the right child.</li><li>Choose your <strong>Relationship</strong> (Father, Mother, Legal guardian or Other).</li><li>Check <strong>Primary contact</strong> if you should be the first point of contact for this child.</li><li>Click <strong>Link</strong> to confirm.</li></ol><p>The child then appears in the <strong>Already linked children</strong> list on this same page, and on your <strong>My children</strong> page.</p><h2 id="following-a-child-s-record" tabindex="-1">Following a child&#39;s record <a class="header-anchor" href="#following-a-child-s-record" aria-label="Permalink to &quot;Following a child&#39;s record&quot;">​</a></h2><p>On a child&#39;s record (opened from <strong>My children</strong>), you&#39;ll find, in order:</p><ul><li><strong>Grades</strong> — per-subject averages for each period, with the annual average shown at the top of the section.</li><li><strong>Lesson log</strong> — the list of lessons given, with date, subject, content and homework assigned.</li><li><strong>Timetable</strong> — the child&#39;s class weekly schedule (day, start time, end time, subject).</li><li><strong>Boarding</strong> — if your child boards at the school, this section shows their site, room and bed, along with their boarding attendance.</li><li><strong>Attendance</strong> — each day with its status (Present, Absent, Late) and, where relevant, the justification note.</li><li><strong>Disciplinary incidents</strong> — date, severity (Minor, Major, Severe), description and any sanction.</li><li><strong>Disciplinary councils</strong> — the disciplinary council sessions held for this child and their decision (warning, reprimand, temporary or permanent exclusion, or no sanction).</li></ul><h2 id="downloading-your-child-s-documents" tabindex="-1">Downloading your child&#39;s documents <a class="header-anchor" href="#downloading-your-child-s-documents" aria-label="Permalink to &quot;Downloading your child&#39;s documents&quot;">​</a></h2><p>From a child&#39;s record, you can download:</p><ul><li><strong>Report cards</strong> — in the &quot;Report cards&quot; section, click <strong>Download</strong> next to the period you want. A report card only appears once the school has published it.</li><li><strong>Payment receipts</strong> — in the payment history (payments section), click <strong>Download receipt</strong> next to a payment; this link only appears if a receipt was generated for that payment.</li><li><strong>Disciplinary council minutes</strong> — in the &quot;Disciplinary councils&quot; section, click <strong>Download minutes</strong> next to a council that has already reached a decision.</li><li><strong>Lesson-log attachments</strong> — when a lesson-log entry has an attached document, an <strong>Attachment</strong> link appears next to that row; click it to open or download the file.</li></ul><h2 id="exporting-the-timetable" tabindex="-1">Exporting the timetable <a class="header-anchor" href="#exporting-the-timetable" aria-label="Permalink to &quot;Exporting the timetable&quot;">​</a></h2><p>To import your child&#39;s timetable into your own calendar (Google Calendar, Apple Calendar, Outlook…):</p><ol><li>On the child&#39;s record, go to the <strong>Timetable</strong> section.</li><li>Click <strong>Export to calendar</strong>.</li><li>An <code>.ics</code> file is downloaded; open it or import it into your usual calendar app to add your child&#39;s classes to your agenda.</li></ol>',18)])])}const p=o(r,[["render",a]]);export{g as __pageData,p as default};
